a=p.parse_args();assert not a.output.exists();plan=json.loads(a.plan.read_text());src=json.loads(Path(plan['source_plan']).read_text());phase=json.loads(Path(plan['phase_review']).read_text());assert src['motions'][0]['id']==phase['rows'][0]['id']=='000041';frames=src['motions'][0]['frames'];known=[s['frame'] for g in phase['rows'][0]['source_contact_support'] if g['mask']=='both_feet_phase_known' for s in g['samples']];index={f:i for i,f in enumerate(known)};P=sp.load_npz(a.directory/'failed_P.npz');A=sp.load_npz(a.directory/'failed_A.npz');z=np.load(a.directory/'failed_vectors.npz');g=z['gradient'];l=z['lower'];u=z['upper'];cut=A.shape[0]-12*len(known);F=A[cut:];target=(l[cut:]+u[cut:])/2;tol=np.tile(np.r_[np.repeat(1e-5,3),np.repeat(1e-4,3)],2);trust=np.r_[np.repeat(.005,3),np.repeat(.05,14)];particular=np.zeros(17*frames);blocks=[];ranks=[]
