N=sp.block_diag(blocks,format='csc');H=(N.T@P@N).tocsc();q=N.T@(P@particular+g);scale=float(H.diagonal().max());B=(A[:cut]@N).tocsc();lower=l[:cut]-A[:cut]@particular;upper=u[:cut]-A[:cut]@particular;rs=1/np.maximum(np.asarray(abs(B).max(axis=1).toarray()).ravel(),1e-12);D=sp.diags(rs);solver=osqp.OSQP();solver.setup(P=sp.triu(H/scale,format='csc'),q=q/scale,A=(D@B).tocsc(),l=rs*lower,u=rs*upper,verbose=False,eps_abs=1e-8,eps_rel=1e-8,max_iter=100000,polishing=True);res=solver.solve();step=particular+N@res.x;violation=float(max(0,(l-A@step).max(),(A@step-u).max()));eqerror=float(abs(F@step-target).max());np.savez_compressed(a.output.parent/'nullspace_qp_step.npz',step=step,particular=particular,reduced_solution=res.x);out=dict(time_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Same firstfit objective and original bounds with stricter linearized feet equalities; not same feasible-set optimum as foot inequalities, no physical acceptance.',status=res.info.status,iterations=res.info.iter,original_variables=P.shape[0],reduced_variables=N.shape[1],known_frames=len(known),foot_ranks=sorted(set(ranks)),unscaled_original_constraint_violation=violation,linearized_foot_equality_error=eqerror,original_gate_pass=bool(res.info.status_val==1 and violation<=1e-7),objective=float(.5*step@(P@step)+g@step),primal_residual=res.info.prim_res,dual_residual=res.info.dual_res);a.output.write_text(json.dumps(out,indent=2)+'\n');print(out,flush=True)
